for j,reg in enumerate(regs):
    print(j,'rect' if is_rect(reg,i) else 'NOT rect','FILL' if any(o[a][b]==4 for a,b in reg) else '')

def solve(i):
    H,W=len(i),len(i[0])
    cnt=Counter(x for row in i for x in row); bg=cnt.most_common(1)[0][0]
    lcs=[x for x in cnt if x!=bg]; lc=lcs[0]
    seen=[[False]*W for _ in range(H)]; offs=[(-1,0),(1,0),(0,-1),(0,1)]
    out=[row[:] for row in i]
    for r in range(H):
        for c in range(W):
            if i[r][c]!=bg or seen[r][c]: continue
            st=[(r,c)]; reg=[]
            while st:
                a,b=st.pop()
                if a<0 or a>=H or b<0 or b>=W or seen[a][b] or i[a][b]==lc: continue
                seen[a][b]=True; reg.append((a,b))
                for dr,dc in offs:
                    rr,cc=a+dr,b+dc
                    if 0<=rr<H and 0<=cc<W and i[rr][cc]!=lc and not seen[rr][cc]: st.append((rr,cc))
            rs=[p[0] for p in reg]; cs=[p[1] for p in reg]
            r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
            if not any(p[0] in (0,H-1) or p[1] in (0,W-1) for p in reg):
                if len(reg)==(r1-r0+1)*(c1-c0+1) and all(i[a][b]==bg for a in range(r0,r1+1) for b in range(c0,c1+1)):
                    for a,b in reg: out[a][b]=4
    return out
